import { configureStore } from '@reduxjs/toolkit';
import rootReducer from './rootReducer';

const STORAGE_KEY = 'app:state:v1';

const loadState = () => {
  try {
    const serialized = localStorage.getItem(STORAGE_KEY);
    if (serialized === null) return undefined;
    return JSON.parse(serialized);
  } catch (e) {
    console.warn('Failed to load state', e);
    return undefined;
  }
};

const saveState = (state) => {
  try {
    const serialized = JSON.stringify(state);
    localStorage.setItem(STORAGE_KEY, serialized);
  } catch (e) {
    console.warn('Failed to save state', e);
  }
};

const preloadedState = loadState();

const store = configureStore({
  reducer: rootReducer,
  preloadedState,
});

store.subscribe(() => {
  saveState(store.getState());
});

export default store;

const CURRENT_VERSION = 2;

const loadState = () => {
  try {
    const raw = localStorage.getItem('app:state');
    if (!raw) return undefined;

    const { version, state } = JSON.parse(raw);
    if (version !== CURRENT_VERSION) {
      console.warn('Discarding stale state');
      return undefined;
    }
    return state;
  } catch {
    return undefined;
  }
};

store.subscribe(() => {
  const payload = { version: CURRENT_VERSION, state: store.getState() };
  localStorage.setItem('app:state', JSON.stringify(payload));
});

let timeoutId;

store.subscribe(() => {
  clearTimeout(timeoutId);
  timeoutId = setTimeout(() => {
    saveState(store.getState());
  }, 500);
});
